root_owned_product_case_observations.exact_original_source:
case XR_CORE_OP_CORE_ATOMIC_LOAD:
case XR_CORE_OP_CORE_ATOMIC_EXCHANGE:
case XR_CORE_OP_CORE_ATOMIC_COMPARE_EXCHANGE:
case XR_CORE_OP_CORE_ATOMIC_UPDATE: {
    bool update = instruction->operation_id == XR_CORE_OP_CORE_ATOMIC_UPDATE;
    bool compare = instruction->operation_id == XR_CORE_OP_CORE_ATOMIC_COMPARE_EXCHANGE;
    bool exchange = update || compare || instruction->operation_id == XR_CORE_OP_CORE_ATOMIC_EXCHANGE;
    if (instruction->operand_count != (compare ? 3u : exchange ? 2u : 1u) || instruction->successor_count != 0u ||
        instruction->immediate_kind != XR_CORE_IR_IMMEDIATE_U32 || (update ? ((instruction->immediate.u32 & 7u) > 4u || (instruction->immediate.u32 >> 3u) > 2u) : instruction->immediate.u32 > 4u) ||
        instruction->result_category != XR_CORE_IR_VALUE || instruction->result_ownership != XR_CORE_IR_NON_OWNER)
        return false;
    const XrValidatedType *type = xr_validated_program_type(ir->program,
        function->value_types[instruction->operands[0]]);
    return type && type->kind == XR_CORE_IR_TYPE_ATOMIC &&
        instruction->result_type_id == type->atomic_element_type &&
        (!update || type->atomic_element_type != XR_CORE_TYPE_F64 || (instruction->immediate.u32 >> 3u) <= 1u) &&
          (!update || type->atomic_element_type != XR_CORE_TYPE_BOOL || (instruction->immediate.u32 >> 3u) == 2u) &&
        function->value_categories[instruction->operands[0]] == XR_CORE_IR_VALUE &&
        (!exchange || (function->value_types[instruction->operands[1]] == type->atomic_element_type &&
            function->value_categories[instruction->operands[1]] == XR_CORE_IR_VALUE &&
            function->value_ownerships[instruction->operands[1]] == XR_CORE_IR_NON_OWNER)) &&
        (!compare || (function->value_types[instruction->operands[2]] == type->atomic_element_type &&
            function->value_categories[instruction->operands[2]] == XR_CORE_IR_VALUE &&
            function->value_ownerships[instruction->operands[2]] == XR_CORE_IR_NON_OWNER));
}

case XR_CORE_OP_CORE_CHANNEL_CONSTRUCT:
    return append_format(buffer,
        "        { int64_t capacity = v%u;\n"
        "          if (capacity < 0 || (uint64_t)capacity > UINT32_MAX ||\n"
        "              (capacity && sizeof(XrChannelMessageOwner) > SIZE_MAX / (uint64_t)capacity))\n"
        "              XR_AOT_FAIL(xr_aot_make(4, 0, 0));\n"
        "          XrChannelStorage *channel = (XrChannelStorage *)malloc(sizeof(*channel));\n"
        "          XrChannelMessageOwner *slots = channel && capacity\n"
        "              ? (XrChannelMessageOwner *)calloc((size_t)capacity, sizeof(*slots)) : NULL;\n"
        "          if (!channel || (capacity && !slots) || !xr_channel_storage_init(channel, slots, (uint32_t)capacity)) {\n"
        "              free(slots); free(channel); XR_AOT_FAIL(xr_aot_make(4, 0, 0));\n"
        "          }\n"
        "          v%u.storage = channel; }\n", instruction->operands[0], instruction->result_id);
case XR_CORE_OP_CORE_CHANNEL_IS_CLOSED:
    return append_format(buffer,
        "        v%u = atomic_load_explicit(&v%u.storage->closed, memory_order_acquire);\n",
        instruction->result_id, instruction->operands[0]);
case XR_CORE_OP_CORE_ATOMIC_CONSTRUCT:
    if (function->value_types[instruction->operands[0]] == XR_CORE_TYPE_F64)
        return append_format(buffer,
            "        { int64_t bits; memcpy(&bits, &v%u, sizeof(bits));\n"
            "          v%u.storage = (XrAtomicStorageCore *)malloc(sizeof(XrAtomicStorageCore));\n"
            "          if (!v%u.storage) XR_AOT_FAIL(xr_aot_make(4, 0, 0));\n"
            "          xr_atomic_storage_init_core(v%u.storage, bits); }\n",
            instruction->operands[0], instruction->result_id,
            instruction->result_id, instruction->result_id);
    return append_format(buffer,
        "        v%u.storage = (XrAtomicStorageCore *)malloc(sizeof(XrAtomicStorageCore));\n"
        "        if (!v%u.storage) { XR_AOT_FAIL(xr_aot_make(4, 0, 0)); }\n"
        "        xr_atomic_storage_init_core(v%u.storage, (int64_t)v%u);\n",
        instruction->result_id, instruction->result_id, instruction->result_id,
        instruction->operands[0]);
case XR_CORE_OP_CORE_ATOMIC_LOAD:
    if (instruction->result_type_id == XR_CORE_TYPE_F64)
        return append_format(buffer,
            "        { int64_t bits = xr_atomic_i64_load_core(&v%u.storage->value, %u);\n"
            "          memcpy(&v%u, &bits, sizeof(bits)); }\n",
            instruction->operands[0], instruction->immediate.u32, instruction->result_id);
    return append_format(buffer, "        v%u = (%s)xr_atomic_i64_load_core(&v%u.storage->value, %u);\n",
        instruction->result_id, instruction->result_type_id == XR_CORE_TYPE_BOOL ? "uint8_t" : "int64_t",
        instruction->operands[0], instruction->immediate.u32);
case XR_CORE_OP_CORE_ATOMIC_UPDATE:
    if (instruction->result_type_id == XR_CORE_TYPE_F64)
        return append_format(buffer,
            "        v%u = xr_atomic_f64_fetch_update_core(&v%u.storage->value, v%u, %u, %u);\n",
            instruction->result_id, instruction->operands[0], instruction->operands[1],
            instruction->immediate.u32 >> 3u, instruction->immediate.u32 & 7u);
    return append_format(buffer,
        "        v%u = (%s)xr_atomic_i64_fetch_%s_core(&v%u.storage->value, (int64_t)v%u, %u);\n",
        instruction->result_id, instruction->result_type_id == XR_CORE_TYPE_BOOL ? "uint8_t" : "int64_t",
        (instruction->immediate.u32 >> 3u) == 0u ? "add" : (instruction->immediate.u32 >> 3u) == 1u ? "sub" : "xor",
        instruction->operands[0], instruction->operands[1], instruction->immediate.u32 & 7u);
case XR_CORE_OP_CORE_ATOMIC_COMPARE_EXCHANGE:
    if (instruction->result_type_id == XR_CORE_TYPE_F64)
        return append_format(buffer,
            "        { int64_t expected, desired;\n"
            "          memcpy(&expected, &v%u, sizeof(expected)); memcpy(&desired, &v%u, sizeof(desired));\n"
            "          (void)xr_atomic_i64_compare_exchange_core(&v%u.storage->value, &expected, desired, %u);\n"
            "          memcpy(&v%u, &expected, sizeof(expected)); }\n",
            instruction->operands[1], instruction->operands[2], instruction->operands[0],
            instruction->immediate.u32, instruction->result_id);
    return append_format(buffer,
        "        { int64_t expected = (int64_t)v%u;\n"
        "          (void)xr_atomic_i64_compare_exchange_core(&v%u.storage->value, &expected, (int64_t)v%u, %u);\n"
        "          v%u = (%s)expected; }\n",
        instruction->operands[1], instruction->operands[0], instruction->operands[2],
        instruction->immediate.u32, instruction->result_id,
        instruction->result_type_id == XR_CORE_TYPE_BOOL ? "uint8_t" : "int64_t");
case XR_CORE_OP_CORE_ATOMIC_EXCHANGE:
    if (instruction->result_type_id == XR_CORE_TYPE_F64)
        return append_format(buffer,
            "        { int64_t bits; memcpy(&bits, &v%u, sizeof(bits));\n"
            "          bits = xr_atomic_i64_exchange_core(&v%u.storage->value, bits, %u);\n"
            "          memcpy(&v%u, &bits, sizeof(bits)); }\n",
            instruction->operands[1], instruction->operands[0], instruction->immediate.u32,
            instruction->result_id);
    return append_format(buffer,
        "        v%u = (%s)xr_atomic_i64_exchange_core(&v%u.storage->value, (int64_t)v%u, %u);\n",
        instruction->result_id, instruction->result_type_id == XR_CORE_TYPE_BOOL ? "uint8_t" : "int64_t",
        instruction->operands[0], instruction->operands[1], instruction->immediate.u32);

case XR_CORE_OP_CORE_CHANNEL_CONSTRUCT: {
    int64_t capacity = values[instruction.operands[0]].as.value.as.i64;
    XrVmChannelValue *value = allocate_channel(context, instruction.result_type_id, capacity);
    if (!value) {
        result = vm_outcome(XR_VM_OUTCOME_RESOURCE_LIMIT, context);
        goto done;
    }
    produced.as.value.kind = XR_VM_VALUE_CHANNEL;
    produced.as.value.as.channel_storage = value;
    break;
}
case XR_CORE_OP_CORE_CHANNEL_IS_CLOSED: {
    const XrVmChannelValue *value = values[instruction.operands[0]].as.value.as.channel_storage;
    produced.as.value.kind = XR_VM_VALUE_BOOL;
    produced.as.value.as.boolean = atomic_load_explicit(&value->shared->closed, memory_order_acquire);
    break;
}
case XR_CORE_OP_CORE_ATOMIC_CONSTRUCT: {
    XrVmValue initial = values[instruction.operands[0]].as.value;
    int64_t bits = initial.kind == XR_VM_VALUE_BOOL ? (initial.as.boolean ? 1 : 0)
                                                    : initial.as.i64;
    if (initial.kind == XR_VM_VALUE_F64)
        memcpy(&bits, &initial.as.f64_bits, sizeof(bits));
    XrVmAtomicValue *value = allocate_atomic(context, instruction.result_type_id, NULL, bits);
    if (!value) {
        result = vm_outcome(XR_VM_OUTCOME_RESOURCE_LIMIT, context);
        goto done;
    }
    produced.as.value.kind = XR_VM_VALUE_ATOMIC;
    produced.as.value.as.atomic_storage = value;
    break;
}
case XR_CORE_OP_CORE_ATOMIC_LOAD:
case XR_CORE_OP_CORE_ATOMIC_EXCHANGE:
case XR_CORE_OP_CORE_ATOMIC_COMPARE_EXCHANGE:
case XR_CORE_OP_CORE_ATOMIC_UPDATE: {
    const XrVmAtomicValue *value = values[instruction.operands[0]].as.value.as.atomic_storage;
    int64_t bits;
    if (instruction.operation_id == XR_CORE_OP_CORE_ATOMIC_UPDATE) {
        XrVmValue operand = values[instruction.operands[1]].as.value;
        int64_t delta = operand.kind == XR_VM_VALUE_BOOL ? (operand.as.boolean ? 1 : 0) : operand.as.i64;
        uint32_t mode = instruction.immediate.u32 >> 3u;
        uint32_t ordering = instruction.immediate.u32 & 7u;
        if (operand.kind == XR_VM_VALUE_F64) {
            double number;
            memcpy(&number, &operand.as.f64_bits, sizeof(number));
            double previous = xr_atomic_f64_fetch_update_core(&value->shared->value, number, mode == 1u, ordering);
            memcpy(&bits, &previous, sizeof(bits));
        } else bits = mode == 0u ? xr_atomic_i64_fetch_add_core(&value->shared->value, delta, ordering)
             : mode == 1u ? xr_atomic_i64_fetch_sub_core(&value->shared->value, delta, ordering)
                          : xr_atomic_i64_fetch_xor_core(&value->shared->value, delta, ordering);
    } else if (instruction.operation_id == XR_CORE_OP_CORE_ATOMIC_COMPARE_EXCHANGE) {
        XrVmValue expected = values[instruction.operands[1]].as.value;
        XrVmValue replacement = values[instruction.operands[2]].as.value;
        bits = expected.kind == XR_VM_VALUE_BOOL ? (expected.as.boolean ? 1 : 0) : expected.as.i64;
        int64_t desired = replacement.kind == XR_VM_VALUE_BOOL ? (replacement.as.boolean ? 1 : 0) : replacement.as.i64;
        if (expected.kind == XR_VM_VALUE_F64) {
            memcpy(&bits, &expected.as.f64_bits, sizeof(bits));
            memcpy(&desired, &replacement.as.f64_bits, sizeof(desired));
        }
        (void)xr_atomic_i64_compare_exchange_core(&value->shared->value, &bits, desired, instruction.immediate.u32);
    } else if (instruction.operation_id == XR_CORE_OP_CORE_ATOMIC_EXCHANGE) {
        XrVmValue replacement = values[instruction.operands[1]].as.value;
        int64_t desired = replacement.kind == XR_VM_VALUE_BOOL ? (replacement.as.boolean ? 1 : 0)
                                                               : replacement.as.i64;
        if (replacement.kind == XR_VM_VALUE_F64)
            memcpy(&desired, &replacement.as.f64_bits, sizeof(desired));
        bits = xr_atomic_i64_exchange_core(&value->shared->value, desired, instruction.immediate.u32);
    } else {
        bits = xr_atomic_i64_load_core(&value->shared->value, instruction.immediate.u32);
    }
    if (instruction.result_type_id == XR_CORE_TYPE_BOOL) {
        produced.as.value.kind = XR_VM_VALUE_BOOL;
        produced.as.value.as.boolean = bits != 0;
    } else if (instruction.result_type_id == XR_CORE_TYPE_F64) {
        produced.as.value.kind = XR_VM_VALUE_F64;
        memcpy(&produced.as.value.as.f64_bits, &bits, sizeof(bits));
    } else {
        produced.as.value.kind = XR_VM_VALUE_I64;
        produced.as.value.as.i64 = bits;
    }
    break;
}
